import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Codebase map","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/reference/CODEBASE.html"}],["meta",{"property":"og:title","content":"Codebase map | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/reference/CODEBASE.html"}],["meta",{"name":"twitter:title","content":"Codebase map | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"reference/CODEBASE.md","filePath":"reference/CODEBASE.md","lastUpdated":1793948169000}`),a={name:`reference/CODEBASE.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="codebase-map" tabindex="-1">Codebase map <a class="header-anchor" href="#codebase-map" aria-label="Permalink to “Codebase map”">​</a></h1><p>This page describes the main runtime boundaries and responsibilities of the shared modules. It is a navigation aid, not a substitute for the implementation.</p><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to “Repository layout”">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>src/core/</code></td><td>Financial domain, normalized simulation context, authoritative runtime/state, event processing, lifecycle and result models.</td></tr><tr><td><code>src/strategies/</code></td><td>Strategy sessions, investment decision logic, hypothetical planning and shared search algorithms.</td></tr><tr><td><code>src/fd-options/</code></td><td>FD option discovery, eligibility and manager-owned candidate ordering.</td></tr><tr><td><code>src/io/</code></td><td>CSV parsing and Node-side data loading.</td></tr><tr><td><code>src/reporting/</code></td><td>Shared console formatting and standalone HTML report generation.</td></tr><tr><td><code>src/cli/</code></td><td>Node.js command-line entry point.</td></tr><tr><td><code>src/web/</code></td><td>Browser application and interactive scenario configuration.</td></tr><tr><td><code>data/</code></td><td>Bank and FD product datasets shared by both runtimes.</td></tr><tr><td><code>schema/</code></td><td>Configuration schema and validation contract.</td></tr><tr><td><code>tests/</code></td><td>Engine, strategy, CLI and browser-facing regression tests.</td></tr><tr><td><code>docs/</code></td><td>User, strategy, architecture and contributor documentation.</td></tr><tr><td><code>archive/</code></td><td>Preserved legacy Python project snapshot.</td></tr></tbody></table><h2 id="runtime-boundaries" tabindex="-1">Runtime boundaries <a class="header-anchor" href="#runtime-boundaries" aria-label="Permalink to “Runtime boundaries”">​</a></h2><p>The Node.js CLI and GitHub Pages web application use the same JavaScript calculation engine. Environment-specific work belongs in adapters: core and strategy modules should not depend on the DOM, Node-only APIs or environment-specific file access.</p><p>The web application exposes Greedy, GSS and Absolute R+ for scoped date-range simulations. Absolute R remains CLI-only for internal verification and testing. Goal mode is disabled in public configuration.</p><h2 id="simulation-lifecycle" tabindex="-1">Simulation lifecycle <a class="header-anchor" href="#simulation-lifecycle" aria-label="Permalink to “Simulation lifecycle”">​</a></h2><p>All production execution enters through <code>SimulationEngine.run(strategy, input)</code>.</p><ul><li><code>simulation-context.js</code> normalizes and validates input, cloning and freezing the values supplied to strategy planning.</li><li><code>simulation-runtime.js</code> owns authoritative balances, actual event progression, outflow settlement, transfer and booking execution, cash-flow scheduling, the event ledger and unfinished result construction.</li><li><code>simulation.js</code> drives revision-bound strategy sessions, adds the simulation-start marker and performs exactly-once finalization.</li><li><code>strategy-contracts.js</code> defines immutable planning views and decision, wait, completion and batch signals.</li><li><code>SimulationState</code> provides revisioned authoritative account values. Strategies receive immutable snapshots, not the state object.</li></ul><p>The runtime processes actual events chronologically. A strategy may request a future wait boundary or return a decision. The runtime validates the decision against the current revision and date, validates the complete plan, and commits staged changes atomically. The final consolidation sweep is simulation-wide and occurs once after the horizon.</p><p>See <a href="./../SIMULATION-LIFECYCLE.html">the simulation lifecycle reference</a>.</p><h2 id="strategy-boundary" tabindex="-1">Strategy boundary <a class="header-anchor" href="#strategy-boundary" aria-label="Permalink to “Strategy boundary”">​</a></h2><p>Production strategies expose <code>createSession(context)</code>; they do not expose a <code>simulate(input)</code> execution method. A session consumes read-only planning views and returns immutable decision signals. It does not own actual event processing, settlement, booking/transfer execution or result construction.</p><ul><li><strong>Greedy</strong> uses <code>pickDailyGreedyPlan()</code> to make local SPLIT/CONSOLIDATE/CARRY decisions from the current view.</li><li><strong>Absolute R+</strong> retains bounded beam search and diagnostics, then emits its selected path as session decisions.</li><li><strong>Absolute R</strong> retains exhaustive branch-and-bound search, then emits its selected path as session decisions.</li><li><strong>GSS</strong> retains recursive scoped planning, forecast contraction and interim-plan exploration in a private hypothetical planner, then emits its selected decision path.</li></ul><p>Hypothetical strategy projections may use local financial/event state to explore possible futures. The authoritative simulation and actual ledger remain in SimulationRuntime.</p><p>See <a href="./../STRATEGIES.html">the strategy guide</a> for decision details.</p><h2 id="fd-option-manager" tabindex="-1">FD option manager <a class="header-anchor" href="#fd-option-manager" aria-label="Permalink to “FD option manager”">​</a></h2><p>FDOptionManager is the shared boundary for FD candidate discovery and ordering. It supplies the eligible candidate list for the relevant account and horizon. Strategies should consume that order rather than duplicating eligibility or rate/tenor ranking rules.</p><p>GSS uses manager-provided candidates and evaluates their viability. It does not independently reorder them by rate or tenor.</p><h2 id="shared-modules" tabindex="-1">Shared modules <a class="header-anchor" href="#shared-modules" aria-label="Permalink to “Shared modules”">​</a></h2><h3 id="core-engine" tabindex="-1">Core engine <a class="header-anchor" href="#core-engine" aria-label="Permalink to “Core engine”">​</a></h3><ul><li><code>simulation-context.js</code>: normalized immutable inputs.</li><li><code>strategy-contracts.js</code>: revision-bound immutable planning views and signals.</li><li><code>simulation-runtime.js</code>: actual chronological execution and result construction.</li><li><code>simulation.js</code>: session driving and finalization.</li><li><code>events.js</code>, <code>cashflows.js</code>, <code>models.js</code>, <code>results.js</code>: shared domain primitives.</li></ul><p>Keep the core runtime-neutral so CLI and browser calculations remain equivalent.</p><h3 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to “Reporting”">​</a></h3><p>The reporting modules generate the common report model and standalone HTML output. The CLI and browser frontends should use the same reporting implementation.</p><h3 id="i-o" tabindex="-1">I/O <a class="header-anchor" href="#i-o" aria-label="Permalink to “I/O”">​</a></h3><p>I/O adapters load and parse external data. Keep filesystem-specific operations outside the shared calculation engine.</p><h3 id="web-application" tabindex="-1">Web application <a class="header-anchor" href="#web-application" aria-label="Permalink to “Web application”">​</a></h3><p>The web frontend configures scenarios, invokes <code>SimulationEngine.run()</code> and presents the resulting report. It should not contain a second implementation of financial or strategy logic.</p><h2 id="related-references" tabindex="-1">Related references <a class="header-anchor" href="#related-references" aria-label="Permalink to “Related references”">​</a></h2><ul><li><a href="./../STRATEGIES.html">Strategy guide</a></li><li><a href="./../SIMULATION-LIFECYCLE.html">Simulation lifecycle</a></li><li><a href="./../strategies/GSS.html">GSS technical reference</a></li><li><a href="./../MIGRATION_PLAN.html">Migration plan</a></li><li><a href="/FD-Calculator/dev/docs/guide/contributing.html">Contributing guide</a></li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/main/README.md" target="_blank" rel="noreferrer">Repository README</a></li></ul>`,32)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};